import * as fs from 'fs';

const logPath = '<tmp>';
const content = fs.readFileSync(logPath, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

const levelCounts: Map<string, number> = new Map();
const componentErrors: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

const regex = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
    const match = line.match(regex);
    if (!match) continue;

    const timestamp = match[1];
    const level = match[2];
    const component = match[3];
    const message = match[4];

    levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

    if (level === 'ERROR') {
        componentErrors.set(component, (componentErrors.get(component) || 0) + 1);
        errorMessages.add(message);
    }

    const hour = timestamp.split(' ')[1].substring(0, 2);
    hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}

let out = '';
out += '=== Log Analysis ===\n';
out += '\n';
out += 'Entries by Level:\n';
const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
    out += `  ${level}: ${count}\n`;
}
out += '\n';

let maxErrComponent = '';
let maxErrCount = 0;
const sortedComps = [...componentErrors.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [comp, count] of sortedComps) {
    if (count > maxErrCount) {
        maxErrCount = count;
        maxErrComponent = comp;
    }
}
out += `Component with Most Errors: ${maxErrComponent} (${maxErrCount} errors)\n`;
out += '\n';

out += 'Unique Error Messages:\n';
const sortedMessages = [...errorMessages].sort((a, b) => a.localeCompare(b));
for (const msg of sortedMessages) {
    out += `  - ${msg}\n`;
}
out += '\n';

let busiestHour = '';
let busiestCount = 0;
const sortedHours = [...hourCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [hour, count] of sortedHours) {
    if (count > busiestCount) {
        busiestCount = count;
        busiestHour = hour;
    }
}
out += `Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)\n`;

process.stdout.write(out);

