import * as fs from 'fs';

const csvPath = '<tmp>';

const content = fs.readFileSync(csvPath, 'utf-8').replace(/^\uFEFF/, '');
const lines = content.trim().split('\n');

interface Employee {
  employee_id: string;
  name: string;
  department: string;
  salary: number;
  start_date: string;
  rating: string;
}

const employees: Employee[] = [];

for (let i = 1; i < lines.length; i++) {
  const parts = lines[i].split(',');
  if (parts.length < 6) continue;
  employees.push({
    employee_id: parts[0].trim(),
    name: parts[1].trim(),
    department: parts[2].trim(),
    salary: parseFloat(parts[3].trim()),
    start_date: parts[4].trim(),
    rating: parts[5].trim()
  });
}

function formatWithCommas(n: number, decimals: number): string {
  const fixed = n.toFixed(decimals);
  const negative = fixed.startsWith('-');
  const absFixed = negative ? fixed.slice(1) : fixed;
  const dotIndex = absFixed.indexOf('.');
  let intPart: string;
  let decPart: string;
  if (dotIndex === -1) {
    intPart = absFixed;
    decPart = '';
  } else {
    intPart = absFixed.slice(0, dotIndex);
    decPart = absFixed.slice(dotIndex);
  }
  const intFormatted = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  const result = (negative ? '-' : '') + intFormatted + decPart;
  return result;
}

const deptSalaries: Map<string, number[]> = new Map();
for (const emp of employees) {
  if (!deptSalaries.has(emp.department)) {
    deptSalaries.set(emp.department, []);
  }
  deptSalaries.get(emp.department)!.push(emp.salary);
}

const sortedDepts = Array.from(deptSalaries.keys()).sort();

let highestEmp = employees[0];
for (const emp of employees) {
  if (emp.salary > highestEmp.salary) {
    highestEmp = emp;
  }
}

const deptCounts: Map<string, number> = new Map();
for (const emp of employees) {
  deptCounts.set(emp.department, (deptCounts.get(emp.department) || 0) + 1);
}

const deptsWithMoreThan2 = Array.from(deptCounts.entries())
  .filter(([_, count]) => count > 2)
  .sort((a, b) => a[0].localeCompare(b[0]));

const totalBudget = employees.reduce((sum, emp) => sum + emp.salary, 0);

const output: string[] = [];
output.push('=== Salary Report ===');
output.push('');
output.push('Average Salary by Department:');
for (const dept of sortedDepts) {
  const salaries = deptSalaries.get(dept)!;
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  output.push(`  ${dept}: $${formatWithCommas(avg, 2)}`);
}
output.push('');
output.push(`Highest Paid: ${highestEmp.name} ($${formatWithCommas(highestEmp.salary, 0)})`);
output.push('');
output.push('Departments with >2 employees:');
for (const [dept, count] of deptsWithMoreThan2) {
  output.push(`  ${dept} (${count} employees)`);
}
output.push('');
output.push(`Total Budget: $${formatWithCommas(totalBudget, 0)}`);

process.stdout.write(output.join('\n') + '\n');

