use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut component_errors: HashMap<String, usize> = HashMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: HashMap<String, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        // Parse: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
        let close_bracket = line.find(']').expect("No closing bracket");
        let timestamp = &line[1..close_bracket];

        let after_bracket = &line[close_bracket + 1..].trim_start();

        let space_pos = after_bracket.find(' ').unwrap_or(after_bracket.len());
        let level = &after_bracket[..space_pos];

        let after_level = &after_bracket[space_pos..].trim_start();
        let open_paren = after_level.find('(').expect("No opening paren");
        let close_paren = after_level.find(')').expect("No closing paren");
        let component = &after_level[open_paren + 1..close_paren];

        let after_component = &after_level[close_paren + 1..].trim_start();
        let message = after_component
            .strip_prefix("- ")
            .unwrap_or(after_component);

        let hour = &timestamp[11..13];
        let hour_key = format!("{}:00", hour);

        *level_counts.entry(level.to_string()).or_insert(0) += 1;
        *hour_counts.entry(hour_key).or_insert(0) += 1;

        if level == "ERROR" {
            *component_errors.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = component_errors
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(c, n)| (c.clone(), *n))
        .unwrap_or_else(|| ("N/A".to_string(), 0));
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts
        .iter()
        .max_by_key(|(_, c)| *c)
        .map(|(h, n)| (h.clone(), *n))
        .unwrap_or_else(|| ("00:00".to_string(), 0));
    println!("Busiest Hour: {} ({} entries)", busiest_hour, busiest_count);
}

