fn format_int_with_commas(n: i64) -> String {
    let s = n.to_string();
    let negative = s.starts_with('-');
    let digits: &str = if negative { &s[1..] } else { s.as_str() };
    let bytes = digits.as_bytes();
    let len = bytes.len();
    let mut result = String::new();
    if negative {
        result.push('-');
    }
    for (i, b) in bytes.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*b as char);
    }
    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");
    let content = content.strip_prefix('\u{feff}').unwrap_or(&content);

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut highest_salary: f64 = f64::MIN;
    let mut highest_name: String = String::new();
