        let department = fields[2].to_string();
        let salary: f64 = fields[3].parse().unwrap_or(0.0);

        dept_salaries.entry(department).or_insert_with(Vec::new).push(salary);

        let salary_int = salary as i64;
        total_budget += salary_int;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }
