        let avg_str = format!("{:.2}", avg);
        let parts: Vec<&str> = avg_str.split('.').collect();
        let int_part = format_int_with_commas(parts[0].parse::<i64>().unwrap_or(0));
        println!("  {}: ${}.{}", dept, int_part, parts[1]);
