for _ in 0..<nodes.count {
    var minNode: String? = nil
    var minDist = Int.max
    for node in nodes {
        if !visited.contains(node) && dist[node]! < minDist {
            minDist = dist[node]!
            minNode = node
        }
    }
    guard let current = minNode else { break }
    visited.insert(current)
    if let neighbors = adj[current] {
        for (neighbor, weight) in neighbors {
            if !visited.contains(neighbor) {
