    public static void main(String[] args) throws Exception {
        URL url = new URL("http://127.0.0.1:18923/api/products");
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString().trim();

        List<String[]> products = parseProducts(json);

        List<String[]> filtered = products.stream()
                .filter(p -> Double.parseDouble(p[2]) > 50.00)
                .sorted(Comparator.comparing(p -> p[1]))
                .collect(Collectors.toList());

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        for (String[] p : filtered) {
            System.out.printf("%s: $%.2f%n", p[1], Double.parseDouble(p[2]));
        }
        System.out.println();
        System.out.println("Count: " + filtered.size());
        double total = filtered.stream().mapToDouble(p -> Double.parseDouble(p[2])).sum();
        System.out.printf("Total: $%.2f%n", total);
    }

    static List<String[]> parseProducts(String json) {
        List<String[]> products = new ArrayList<>();
        if (json.startsWith("[")) json = json.substring(1);
        if (json.endsWith("]")) json = json.substring(0, json.length() - 1);

        int i = 0;
        while (i < json.length()) {
            int start = json.indexOf('{', i);
            if (start == -1) break;
            int end = json.indexOf('}', start);
            if (end == -1) break;

            String obj = json.substring(start + 1, end);
            String name = extractString(obj, "name");
            String price = extractNumber(obj, "price");

            products.add(new String[]{"", name, price});
            i = end + 1;
        }
        return products;
    }

    static String extractString(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int idx = obj.indexOf(pattern);
        if (idx == -1) return "";
        idx += pattern.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        idx++;
        while (idx < obj.length() && obj.charAt(idx) != '"') idx++;
        idx++;
        int start = idx;
        while (idx < obj.length() && obj.charAt(idx) != '"') {
            if (obj.charAt(idx) == '\\' && idx + 1 < obj.length()) {
                idx += 2;
            } else {
                idx++;
            }
        }
        return obj.substring(start, idx).replace("\\\"", "\"");
    }

    static String extractNumber(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int idx = obj.indexOf(pattern);
        if (idx == -1) return "0";
        idx += pattern.length();
        while (idx < obj.length() && obj.charAt(idx) != ':') idx++;
        idx++;
        while (idx < obj.length() && obj.charAt(idx) == ' ') idx++;
        int start = idx;
        while (idx < obj.length() && (Character.isDigit(obj.charAt(idx)) || obj.charAt(idx) == '.' || obj.charAt(idx) == '-' || obj.charAt(idx) == '+')) {
            idx++;
        }
        String num = obj.substring(start, idx);
        return num.isEmpty() ? "0" : num;
    }
}

