import Foundation

func readJSON(from path: String) -> Any {
    let url = URL(fileURLWithPath: path)
    let data = try! Data(contentsOf: url)
    let obj = try! JSONSerialization.jsonObject(with: data, options: [])
    return obj
}

func canonicalString(_ value: Any) -> String {
    let data = try! JSONSerialization.data(withJSONObject: value, options: [.sortedKeys])
    return String(data: data, encoding: .utf8)!
}

func deepMerge(_ a: Any, _ b: Any) -> Any {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        var result = dictA
        for (key, value) in dictB {
            if let existingValue = result[key] {
                result[key] = deepMerge(existingValue, value)
            } else {
                result[key] = value
            }
        }
        return result
    }
    if let arrA = a as? [Any], let arrB = b as? [Any] {
        var result = arrA
        var seen = Set<String>(arrA.map { canonicalString($0) })
        for item in arrB {
            let cs = canonicalString(item)
            if !seen.contains(cs) {
                result.append(item)
                seen.insert(cs)
            }
        }
