interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface Graph {
  nodes: string[];
  edges: Edge[];
}

class MinHeap {
  private heap: { key: number; value: string }[] = [];

  push(key: number, value: string): void {
    this.heap.push({ key, value });
    this.bubbleUp(this.heap.length - 1);
  }

  pop(): { key: number; value: string } | undefined {
    if (this.heap.length === 0) return undefined;
    const top = this.heap[0];
    const last = this.heap.pop()!;
    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.bubbleDown(0);
    }
    return top;
  }

  get size(): number {
    return this.heap.length;
  }

  private bubbleUp(idx: number): void {
    while (idx > 0) {
      const parent = Math.floor((idx - 1) / 2);
      if (this.heap[parent].key <= this.heap[idx].key) break;
      const tmp = this.heap[parent];
      this.heap[parent] = this.heap[idx];
      this.heap[idx] = tmp;
      idx = parent;
    }
  }

  private bubbleDown(idx: number): void {
    const n = this.heap.length;
    for (;;) {
      let smallest = idx;
      const left = 2 * idx + 1;
      const right = 2 * idx + 2;
      if (left < n && this.heap[left].key < this.heap[smallest].key) smallest = left;
      if (right < n && this.heap[right].key < this.heap[smallest].key) smallest = right;
      if (smallest === idx) break;
      const tmp = this.heap[smallest];
      this.heap[smallest] = this.heap[idx];
      this.heap[idx] = tmp;
      idx = smallest;
    }
  }
}

function main(): void {
  const raw = fs.readFileSync(
    '<tmp>',
    'utf-8'
  );
  const data: Graph = JSON.parse(raw);

  const adj = new Map<string, { node: string; weight: number }[]>();
  for (const node of data.nodes) {
    adj.set(node, []);
  }
  for (const edge of data.edges) {
    adj.get(edge.from)!.push({ node: edge.to, weight: edge.weight });
    adj.get(edge.to)!.push({ node: edge.from, weight: edge.weight });
  }

  const dist = new Map<string, number>();
  for (const node of data.nodes) {
    dist.set(node, Infinity);
  }
  dist.set('A', 0);

  const pq = new MinHeap();
  pq.push(0, 'A');

  while (pq.size > 0) {
    const item = pq.pop()!;
    const u = item.value;
    const d = item.key;
    if (d > dist.get(u)!) continue;
    const neighbors = adj.get(u)!;
    for (const { node: v, weight } of neighbors) {
      const nd = d + weight;
      if (nd < dist.get(v)!) {
        dist.set(v, nd);
        pq.push(nd, v);
      }
    }
  }

