#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *run_command(const char *cmd) {
    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) return NULL;

    FILE *fp = popen(cmd, "r");
    if (!fp) {
        free(buf);
        return NULL;
    }

    size_t total = 0;
    size_t n;
    while ((n = fread(buf + total, 1, cap - total - 1, fp)) > 0) {
        total += n;
        if (total + 1 >= cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) {
                pclose(fp);
                free(buf);
                return NULL;
            }
            buf = tmp;
        }
    }
    buf[total] = '\0';
    pclose(fp);

    /* Strip trailing whitespace (newlines, CR, spaces, tabs) */
    while (total > 0) {
        char c = buf[total - 1];
        if (c == '\n' || c == '\r' || c == ' ' || c == '\t') {
            buf[--total] = '\0';
        } else {
            break;
        }
    }
    return buf;
}

int main(void) {
    char *hostname = run_command("hostname");
    char *os       = run_command("uname -s");
    char *arch     = run_command("uname -m");
    char *username = run_command("whoami");

    if (!hostname) { free(hostname); hostname = strdup("unknown"); }
    if (!os)       { free(os);       os       = strdup("unknown"); }
    if (!arch)     { free(arch);     arch     = strdup("unknown"); }
