import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(content: Buffer): number {
  if (content.length === 0) return 0;
  let count = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 10) count++;
  }
  if (content[content.length - 1] !== 10) count++;
  return count;
}

function walk(dir: string, root: string, visited: Set<string>, results: FileInfo[]): void {
  let realDir: string;
  try {
    realDir = fs.realpathSync(dir);
  } catch {
    return;
  }
  if (visited.has(realDir)) return;
  visited.add(realDir);

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) {
      continue;
    } else if (entry.isDirectory()) {
      walk(fullPath, root, visited, results);
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      let content: Buffer;
      try {
        content = fs.readFileSync(fullPath);
      } catch {
        continue;
      }
      const lines = countLines(content);
      const chars = content.length;
      results.push({ relativePath, lines, chars });
    }
  }
}

const results: FileInfo[] = [];
const visited = new Set<string>();
walk(rootDir, rootDir, visited, results);

const groups = new Map<string, FileInfo[]>();
