use std::io::{Read, Write};
use std::net::TcpStream;

enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input: input.as_bytes(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && matches!(self.input[self.pos], b' ' | b'\t' | b'\n' | b'\r') {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }

    fn expect(&mut self, c: u8) {
        self.skip_whitespace();
        assert_eq!(self.peek(), Some(c), "Expected '{}' at position {}", c as char, self.pos);
        self.pos += 1;
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_whitespace();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => JsonValue::String(self.parse_string()),
            Some(b't') => {
                self.parse_literal("true");
                JsonValue::Bool(true)
            }
            Some(b'f') => {
                self.parse_literal("false");
                JsonValue::Bool(false)
            }
            Some(b'n') => {
                self.parse_literal("null");
                JsonValue::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_literal(&mut self, lit: &str) {
        for c in lit.bytes() {
            assert_eq!(self.input[self.pos], c, "Parse error at position {}", self.pos);
            self.pos += 1;
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect(b'"');
        let mut s = String::new();
        loop {
            let c = self.input[self.pos];
            self.pos += 1;
            if c == b'"' {
                break;
            }
            if c == b'\\' {
                let esc = self.input[self.pos];
                self.pos += 1;
                match esc {
                    b'"' => s.push('"'),
                    b'\\' => s.push('\\'),
                    b'/' => s.push('/'),
                    b'b' => s.push('\x08'),
                    b'f' => s.push('\x0C'),
                    b'n' => s.push('\n'),
                    b'r' => s.push('\r'),
                    b't' => s.push('\t'),
                    b'u' => {
                        let hex = std::str::from_utf8(&self.input[self.pos..self.pos + 4]).unwrap();
                        let cp = u32::from_str_radix(hex, 16).unwrap();
                        self.pos += 4;
                        s.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                    }
                    _ => panic!("Invalid escape character"),
                }
            } else {
                s.push(c as char);
            }
        }
        s
    }

    fn parse_number(&mut self) -> JsonValue {
        self.skip_whitespace();
        let start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c.is_ascii_digit() || matches!(c, b'-' | b'+' | b'.' | b'e' | b'E') {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos]).unwrap();
        JsonValue::Number(s.parse::<f64>().unwrap())
    }

    fn parse_array(&mut self) -> JsonValue {
        self.expect(b'[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return JsonValue::Array(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b']') => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        JsonValue::Array(items)
    }

    fn parse_object(&mut self) -> JsonValue {
        self.expect(b'{');
        let mut fields = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return JsonValue::Object(fields);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(b':');
            let val = self.parse_value();
            fields.push((key, val));
            self.skip_whitespace();
            match self.peek() {
                Some(b',') => {
                    self.pos += 1;
                }
                Some(b'}') => {
                    self.pos += 1;
                    break;
                }
                _ => panic!("Expected ',' or '}}' in object"),
            }
        }
        JsonValue::Object(fields)
    }
}

fn parse_json(input: &[u8]) -> JsonValue {
    let s = std::str::from_utf8(input).unwrap();
    let mut parser = Parser::new(s);
    parser.parse_value()
}

fn dechunk(body: &str) -> String {
    let mut result = String::new();
    let bytes = body.as_bytes();
    let mut pos = 0;
    while pos < bytes.len() {
        let mut nl = pos;
        while nl < bytes.len() && bytes[nl] != b'\n' {
            nl += 1;
        }
        if nl >= bytes.len() {
            break;
        }
        let size_line = &bytes[pos..nl];
        let size_str = if size_line.last() == Some(&b'\r') {
            &size_line[..size_line.len() - 1]
        } else {
            size_line
        };
        let size = usize::from_str_radix(std::str::from_utf8(size_str).unwrap(), 16).unwrap();
        pos = nl + 1;
        if size == 0 {
            break;
        }
        result.push_str(std::str::from_utf8(&bytes[pos..pos + size]).unwrap());
        pos += size + 2;
    }
    result
}

fn http_get(host: &str, port: u16, path: &str) -> String {
    let mut stream = TcpStream::connect((host, port)).unwrap();
    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}:{}\r\nConnection: close\r\n\r\n",
        path, host, port
    );
    stream.write_all(request.as_bytes()).unwrap();

    let mut response = Vec::new();
    let mut buf = [0u8; 8192];
    loop {
        let n = stream.read(&mut buf).unwrap();
        if n == 0 {
            break;
        }
        response.extend_from_slice(&buf[..n]);
    }

    let response_str = String::from_utf8(response).unwrap();
    let header_end = response_str.find("\r\n\r\n").unwrap();
    let headers = &response_str[..header_end];
    let body = &response_str[header_end + 4..];

    let headers_lower = headers.to_lowercase();
    if headers_lower.contains("transfer-encoding: chunked") {
        dechunk(body)
    } else {
        body.to_string()
    }
}

fn get_field<'a>(obj: &'a JsonValue, key: &str) -> Option<&'a JsonValue> {
    if let JsonValue::Object(fields) = obj {
        for (k, v) in fields {
            if k == key {
                return Some(v);
            }
        }
    }
    None
}

fn main() {
    let body = http_get("127.0.0.1", 18923, "/api/products");
    let json = parse_json(body.as_bytes());

    let products = match &json {
        JsonValue::Array(items) => items,
        _ => panic!("Expected JSON array"),
    };

    let mut filtered: Vec<(String, f64)> = products
        .iter()
        .filter_map(|p| {
            let price = get_field(p, "price")?;
            let price = if let JsonValue::Number(n) = price { *n } else { return None };
            if price > 50.00 {
                let name = get_field(p, "name")?;
                let name = if let JsonValue::String(s) = name { s.clone() } else { return None };
                Some((name, price))
            } else {
                None
            }
        })
        .collect();

    filtered.sort_by(|a, b| a.0.cmp(&b.0));

    let total: f64 = filtered.iter().map(|(_, p)| p).sum();

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &filtered {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", filtered.len());
    println!("Total: ${:.2}", total);
}

