#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE 8192

static char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *p = malloc(len);
    if (p) memcpy(p, s, len);
    return p;
}

typedef struct {
    char *name;
    int count;
} NameCount;

int cmp_name_count(const void *a, const void *b) {
    const NameCount *na = *(const NameCount *const *)a;
    const NameCount *nb = *(const NameCount *const *)b;
    return strcmp(na->name, nb->name);
}

int cmp_msg(const void *a, const void *b) {
    const char *ma = *(const char *const *)a;
    const char *mb = *(const char *const *)b;
    return strcmp(ma, mb);
}

int main(void) {
    const char *filepath = "<tmp>";

    FILE *f = fopen(filepath, "r");
    if (!f) {
        fprintf(stderr, "Cannot open file\n");
        return 1;
    }

    NameCount *levels = NULL;
    int n_levels = 0, cap_levels = 0;

    NameCount *components = NULL;
    int n_components = 0, cap_components = 0;

    char **error_msgs = NULL;
    int n_err_msgs = 0, cap_err_msgs = 0;

    int hour_counts[24] = {0};

    char *line = malloc(MAX_LINE);
    if (!line) { fclose(f); return 1; }

    while (fgets(line, MAX_LINE, f)) {
        size_t len = strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (len < 21) continue;

        if (line[0] != '[') continue;

        int hour = (line[12] - '0') * 10 + (line[13] - '0');
        if (hour < 0 || hour > 23) continue;
        hour_counts[hour]++;

        char *close_bracket = strchr(line, ']');
        if (!close_bracket) continue;

        char *p = close_bracket + 1;
        if (*p == ' ') p++;

        char *level_start = p;
        while (*p && *p != ' ') p++;
        char *level_end = p;
        *level_end = '\0';

        if (*p == ' ') p++;
        if (*p != '(') { *level_end = ' '; continue; }
        char *comp_start = p + 1;
        char *comp_end = strchr(comp_start, ')');
        if (!comp_end) { *level_end = ' '; continue; }
        *comp_end = '\0';

        p = comp_end + 1;
        while (*p == ' ') p++;
        if (*p == '-' && (p[1] == ' ' || p[1] == '\0')) {
            p++;
            while (*p == ' ') p++;
        }
        char *msg_start = p;

        int found_level = 0;
        for (int i = 0; i < n_levels; i++) {
            if (strcmp(levels[i].name, level_start) == 0) {
                levels[i].count++;
                found_level = 1;
                break;
            }
        }
        if (!found_level) {
            if (n_levels == cap_levels) {
                cap_levels = cap_levels ? cap_levels * 2 : 16;
                levels = realloc(levels, cap_levels * sizeof(NameCount));
            }
            levels[n_levels].name = my_strdup(level_start);
            levels[n_levels].count = 1;
            n_levels++;
        }

        if (strcmp(level_start, "ERROR") == 0) {
            int found_comp = 0;
            for (int i = 0; i < n_components; i++) {
                if (strcmp(components[i].name, comp_start) == 0) {
                    components[i].count++;
                    found_comp = 1;
                    break;
                }
            }
            if (!found_comp) {
                if (n_components == cap_components) {
                    cap_components = cap_components ? cap_components * 2 : 16;
                    components = realloc(components, cap_components * sizeof(NameCount));
                }
                components[n_components].name = my_strdup(comp_start);
                components[n_components].count = 1;
                n_components++;
            }

            int found_msg = 0;
            for (int i = 0; i < n_err_msgs; i++) {
                if (strcmp(error_msgs[i], msg_start) == 0) {
                    found_msg = 1;
                    break;
                }
            }
            if (!found_msg) {
                if (n_err_msgs == cap_err_msgs) {
                    cap_err_msgs = cap_err_msgs ? cap_err_msgs * 2 : 16;
                    error_msgs = realloc(error_msgs, cap_err_msgs * sizeof(char *));
                }
                error_msgs[n_err_msgs] = my_strdup(msg_start);
                n_err_msgs++;
            }
        }
    }

    free(line);
    fclose(f);

    NameCount **level_ptrs = NULL;
    if (n_levels > 0) {
        level_ptrs = malloc(n_levels * sizeof(NameCount *));
        for (int i = 0; i < n_levels; i++) level_ptrs[i] = &levels[i];
        qsort(level_ptrs, n_levels, sizeof(NameCount *), cmp_name_count);
    }

    int best_comp = -1;
    int best_count = 0;
    for (int i = 0; i < n_components; i++) {
        if (components[i].count > best_count) {
            best_count = components[i].count;
            best_comp = i;
        }
    }

    if (n_err_msgs > 1)
        qsort(error_msgs, n_err_msgs, sizeof(char *), cmp_msg);

    int busiest_hour = 0;
    int busiest_count = 0;
    for (int i = 0; i < 24; i++) {
        if (hour_counts[i] > busiest_count) {
            busiest_count = hour_counts[i];
            busiest_hour = i;
        }
    }

    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < n_levels; i++) {
        printf("  %s: %d\n", level_ptrs[i]->name, level_ptrs[i]->count);
    }
    printf("\n");
    if (best_comp >= 0) {
        printf("Component with Most Errors: %s (%d errors)\n", components[best_comp].name, best_count);
    } else {
        printf("Component with Most Errors: N/A (0 errors)\n");
    }
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < n_err_msgs; i++) {
        printf("  - %s\n", error_msgs[i]);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", busiest_hour, busiest_count);

    if (level_ptrs) free(level_ptrs);
    for (int i = 0; i < n_levels; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < n_components; i++) free(components[i].name);
    free(components);
    for (int i = 0; i < n_err_msgs; i++) free(error_msgs[i]);
    free(error_msgs);

    return 0;
}

