import Foundation

let rootDir = "<tmp>"
let fileManager = FileManager.default
let rootURL = URL(fileURLWithPath: rootDir)

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var files: [String: [FileInfo]] = [:]
var visitedDirs: Set<String> = []

func walk(_ url: URL) {
    let path = url.path
    if visitedDirs.contains(path) { return }

    var isDir: ObjCBool = false
    guard fileManager.fileExists(atPath: path, isDirectory: &isDir) else { return }

    if isDir.boolValue {
        visitedDirs.insert(path)
        guard let contents = try? fileManager.contentsOfDirectory(
            at: url,
            includingPropertiesForKeys: [.isSymbolicLinkKey],
            options: []
        ) else { return }
        for child in contents {
            let isSymlink = (try? child.resourceValues(forKeys: [.isSymbolicLinkKey]))?.isSymbolicLink ?? false
            if isSymlink { continue }
            walk(child)
        }
    } else {
        let isSymlink = (try? url.resourceValues(forKeys: [.isSymbolicLinkKey]))?.isSymbolicLink ?? false
        if isSymlink { return }

        let relativePath = path.replacingOccurrences(of: rootDir + "/", with: "")

        let data = (try? Data(contentsOf: url)) ?? Data()
        let charCount = data.count

        let content = String(data: data, encoding: .utf8) ?? ""
        let lines: Int
        if content.isEmpty {
            lines = 0
        } else {
            let lineCount = content.components(separatedBy: "\n").count
            if content.hasSuffix("\n") {
                lines = lineCount - 1
            } else {
                lines = lineCount
            }
        }

        let ext = url.pathExtension
        let extKey = ext.isEmpty ? "" : "." + ext

        let info = FileInfo(relativePath: relativePath, lines: lines, chars: charCount)
        if files[extKey] == nil {
            files[extKey] = []
        }
        files[extKey]!.append(info)
    }
}

walk(rootURL)

var output: [String] = []
output.append("=== File Tree Analysis ===")
output.append("")

let sortedExts = files.keys.sorted()
var totalFiles = 0
var totalLines = 0
var totalChars = 0

for ext in sortedExts {
    let extFiles = files[ext]!
    let sortedFiles = extFiles.sorted { $0.relativePath < $1.relativePath }

    let extLines = sortedFiles.reduce(0) { $0 + $1.lines }
    let extChars = sortedFiles.reduce(0) { $0 + $1.chars }

    output.append("Extension: \(ext)")
    output.append("  Files: \(sortedFiles.count)")
    output.append("  Total Lines: \(extLines)")
    output.append("  Total Characters: \(extChars)")
    for f in sortedFiles {
        output.append("    \(f.relativePath): \(f.lines) lines, \(f.chars) chars")
    }

    totalFiles += sortedFiles.count
    totalLines += extLines
    totalChars += extChars
}

output.append("")
output.append("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")

