#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_value {
    json_type type;
    int boolean;
    double number;
    char *string;
    struct json_value **items;
    int item_count;
    int item_cap;
    char **keys;
    struct json_value **values;
    int pair_count;
    int pair_cap;
} json_value;

static json_value *json_new(void) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    return v;
}

static void json_free(json_value *v) {
    if (!v) return;
    if (v->type == JSON_STRING && v->string) free(v->string);
    if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->item_count; i++) json_free(v->items[i]);
        free(v->items);
    }
    if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->pair_count; i++) {
            free(v->keys[i]);
            json_free(v->values[i]);
        }
        free(v->keys);
        free(v->values);
    }
    free(v);
}

static void skip_whitespace(const char *buf, int *pos) {
    while (*pos < (int)strlen(buf) && (buf[*pos] == ' ' || buf[*pos] == '\t' ||
           buf[*pos] == '\n' || buf[*pos] == '\r'))
        (*pos)++;
}

static json_value *json_parse_string_raw(const char *buf, int *pos) {
    json_value *v = json_new();
    v->type = JSON_STRING;
    if (*pos >= (int)strlen(buf) || buf[*pos] != '"') {
        fprintf(stderr, "Expected string at pos %d\n", *pos);
        exit(1);
    }
    (*pos)++;
    int cap = 256;
    char *s = (char *)malloc(cap);
    int len = 0;
    while (*pos < (int)strlen(buf) && buf[*pos] != '"') {
        char c = buf[*pos];
        if (c == '\\') {
            (*pos)++;
            char esc = buf[*pos];
            switch (esc) {
                case '"': s[len++] = '"'; break;
                case '\\': s[len++] = '\\'; break;
                case '/': s[len++] = '/'; break;
                case 'b': s[len++] = '\b'; break;
                case 'f': s[len++] = '\f'; break;
                case 'n': s[len++] = '\n'; break;
                case 'r': s[len++] = '\r'; break;
                case 't': s[len++] = '\t'; break;
                case 'u': {
                    (*pos)++;
                    int code = 0;
                    for (int i = 0; i < 4; i++) {
                        char h = buf[*pos];
                        code <<= 4;
                        if (h >= '0' && h <= '9') code |= (h - '0');
                        else if (h >= 'a' && h <= 'f') code |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') code |= (h - 'A' + 10);
                        else { fprintf(stderr, "Bad unicode escape\n"); exit(1); }
                        (*pos)++;
                    }
                    /* Encode as UTF-8 */
                    if (code < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
                        s[len++] = (char)code;
                    } else if (code < 0x800) {
                        if (len + 2 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
                        s[len++] = (char)(0xC0 | (code >> 6));
                        s[len++] = (char)(0x80 | (code & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
                        s[len++] = (char)(0xE0 | (code >> 12));
                        s[len++] = (char)(0x80 | ((code >> 6) & 0x3F));
                        s[len++] = (char)(0x80 | (code & 0x3F));
                    }
                    break;
                }
                default:
                    s[len++] = esc;
                    break;
            }
            (*pos)++;
        } else {
            if (len + 1 >= cap) { cap *= 2; s = (char *)realloc(s, cap); }
            s[len++] = c;
            (*pos)++;
        }
    }
    if (*pos >= (int)strlen(buf)) {
        fprintf(stderr, "Unterminated string\n");
        exit(1);
    }
    (*pos)++; /* closing quote */
    if (len + 1 >= cap) { cap = len + 1; s = (char *)realloc(s, cap); }
    s[len] = '\0';
    v->string = s;
    return v;
}

static json_value *json_parse_number(const char *buf, int *pos) {
    json_value *v = json_new();
    v->type = JSON_NUMBER;
    char *end;
    v->number = strtod(buf + *pos, &end);
    *pos = (int)(end - buf);
    return v;
}

static json_value *json_parse_literal(const char *buf, int *pos) {
    json_value *v = json_new();
    int len = (int)strlen(buf);
    if (*pos + 4 <= len && strncmp(buf + *pos, "true", 4) == 0) {
        v->type = JSON_BOOL;
