static void sort_object(json_value *obj) {
    if (obj->type != JSON_OBJECT || obj->pair_count <= 1) {
        if (obj->type == JSON_OBJECT) {
            for (int i = 0; i < obj->pair_count; i++)
                sort_object(obj->values[i]);
        } else if (obj->type == JSON_ARRAY) {
            for (int i = 0; i < obj->item_count; i++)
                sort_object(obj->items[i]);
        }
        return;
    }
    /* Sort keys alphabetically using insertion sort for simplicity */
    for (int i = 1; i < obj->pair_count; i++) {
        char *key = obj->keys[i];
        json_value *val = obj->values[i];
        int j = i - 1;
        while (j >= 0 && strcmp(obj->keys[j], key) > 0) {
            obj->keys[j + 1] = obj->keys[j];
            obj->values[j + 1] = obj->values[j];
            j--;
        }
        obj->keys[j + 1] = key;
        obj->values[j + 1] = val;
    }
    for (int i = 0; i < obj->pair_count; i++)
