}

static int json_equal(const json_value *a, const json_value *b) {
    if (!a || !b) return a == b;
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->number == b->number;
        case JSON_STRING: return strcmp(a->string, b->string) == 0;
        case JSON_ARRAY:
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++)
                if (!json_equal(a->items[i], b->items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->pair_count != b->pair_count) return 0;
            for (int i = 0; i < a->pair_count; i++) {
                int found = 0;
                for (int j = 0; j < b->pair_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) {
                        if (!json_equal(a->values[i], b->values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

