    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new();
        result->type = JSON_ARRAY;
        result->item_cap = a->item_count + b->item_count + 1;
        result->items = (json_value **)malloc(sizeof(json_value *) * result->item_cap);
        result->item_count = 0;

