static void sort_object(json_value *obj) {
    if (obj->type != JSON_OBJECT || obj->pair_count <= 1) {
        if (obj->type == JSON_OBJECT) {
            for (int i = 0; i < obj->pair_count; i++)
                sort_object(obj->values[i]);
        } else if (obj->type == JSON_ARRAY) {
            for (int i = 0; i < obj->item_count; i++)
                sort_object(obj->items[i]);
        }
        return;
    }
    /* Sort keys alphabetically using insertion sort for simplicity */
    for (int i = 1; i < obj->pair_count; i++) {
        char *key = obj->keys[i];
        json_value *val = obj->values[i];
        int j = i - 1;
        while (j >= 0 && strcmp(obj->keys[j], key) > 0) {
            obj->keys[j + 1] = obj->keys[j];
            obj->values[j + 1] = obj->values[j];
            j--;
        }
        obj->keys[j + 1] = key;
        obj->values[j + 1] = val;
    }
    for (int i = 0; i < obj->pair_count; i++)
        sort_object(obj->values[i]);
}

static void print_string_escaped(const char *s) {
    putchar('"');
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if (c < 0x20)
                    printf("\\u%04x", c);
                else
                    putchar(c);
                break;
        }
    }
    putchar('"');
}

static void print_number(double n) {
    if (n == floor(n) && fabs(n) < 1e15) {
        long long ll = (long long)n;
        printf("%lld", ll);
    } else {
        /* Use enough precision */
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", n);
        /* Remove trailing zeros but keep at least one decimal */
        fputs(buf, stdout);
    }
}

