static json_value *json_parse(const char *buf, int *pos) {
    skip_whitespace(buf, pos);
    if (*pos >= (int)strlen(buf)) {
        fprintf(stderr, "Unexpected end of input\n");
        exit(1);
    }
    char c = buf[*pos];
    if (c == '{') return json_parse_object(buf, pos);
    if (c == '[') return json_parse_array(buf, pos);
    if (c == '"') return json_parse_string_raw(buf, pos);
    if (c == '-' || (c >= '0' && c <= '9')) return json_parse_number(buf, pos);
    if (c == 't' || c == 'f' || c == 'n') return json_parse_literal(buf, pos);
    fprintf(stderr, "Unexpected char '%c' at pos %d\n", c, *pos);
    exit(1);
    return NULL;
}

static json_value *deep_copy(const json_value *v) {
    if (!v) return NULL;
    json_value *c = json_new();
    c->type = v->type;
    c->boolean = v->boolean;
    c->number = v->number;
    if (v->type == JSON_STRING) {
        c->string = strdup(v->string);
    } else if (v->type == JSON_ARRAY) {
        c->item_cap = v->item_count > 0 ? v->item_count : 1;
        c->items = (json_value **)malloc(sizeof(json_value *) * c->item_cap);
        c->item_count = v->item_count;
        for (int i = 0; i < v->item_count; i++)
            c->items[i] = deep_copy(v->items[i]);
    } else if (v->type == JSON_OBJECT) {
        c->pair_cap = v->pair_count > 0 ? v->pair_count : 1;
        c->keys = (char **)malloc(sizeof(char *) * c->pair_cap);
        c->values = (json_value **)malloc(sizeof(json_value *) * c->pair_cap);
        c->pair_count = v->pair_count;
        for (int i = 0; i < v->pair_count; i++) {
            c->keys[i] = strdup(v->keys[i]);
            c->values[i] = deep_copy(v->values[i]);
        }
    }
    return c;
}

static int json_equal(const json_value *a, const json_value *b) {
    if (!a || !b) return a == b;
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->number == b->number;
        case JSON_STRING: return strcmp(a->string, b->string) == 0;
        case JSON_ARRAY:
            if (a->item_count != b->item_count) return 0;
            for (int i = 0; i < a->item_count; i++)
                if (!json_equal(a->items[i], b->items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->pair_count != b->pair_count) return 0;
            for (int i = 0; i < a->pair_count; i++) {
                int found = 0;
                for (int j = 0; j < b->pair_count; j++) {
                    if (strcmp(a->keys[i], b->keys[j]) == 0) {
                        if (!json_equal(a->values[i], b->values[j])) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

static int array_contains(const json_value *arr, const json_value *item) {
