static void sort_object(json_value *obj) {
    if (!obj) return;
    if (obj->type == JSON_OBJECT) {
        for (int i = 0; i < obj->pair_count; i++)
            sort_object(obj->values[i]);
        if (obj->pair_count <= 1) return;
        for (int i = 1; i < obj->pair_count; i++) {
            char *key = obj->keys[i];
            json_value *val = obj->values[i];
            int j = i - 1;
            while (j >= 0 && strcmp(obj->keys[j], key) > 0) {
                obj->keys[j + 1] = obj->keys[j];
                obj->values[j + 1] = obj->values[j];
                j--;
            }
            obj->keys[j + 1] = key;
            obj->values[j + 1] = val;
        }
    } else if (obj->type == JSON_ARRAY) {
        for (int i = 0; i < obj->item_count; i++)
            sort_object(obj->items[i]);
    }
}

static void print_string_escaped(const char *s) {
    putchar('"');
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if (c < 0x20)
                    printf("\\u%04x", c);
                else
                    putchar(c);
                break;
        }
    }
    putchar('"');
}

static void print_number(double n) {
    if (n == floor(n) && fabs(n) < 1e15) {
        long long ll = (long long)n;
        printf("%lld", ll);
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", n);
        fputs(buf, stdout);
    }
}

static void json_print(const json_value *v, int indent) {
    if (!v) {
        printf("null");
        return;
    }
    switch (v->type) {
        case JSON_NULL:
            printf("null");
            break;
        case JSON_BOOL:
            printf(v->boolean ? "true" : "false");
            break;
        case JSON_NUMBER:
            print_number(v->number);
            break;
        case JSON_STRING:
            print_string_escaped(v->string);
            break;
        case JSON_ARRAY:
            if (v->item_count == 0) {
                printf("[]");
                break;
            }
            printf("[\n");
            for (int i = 0; i < v->item_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) putchar(' ');
                json_print(v->items[i], indent + 1);
                if (i < v->item_count - 1) putchar(',');
                putchar('\n');
            }
            for (int s = 0; s < indent * 2; s++) putchar(' ');
            printf("]");
            break;
        case JSON_OBJECT:
            if (v->pair_count == 0) {
                printf("{}");
                break;
            }
            printf("{\n");
            for (int i = 0; i < v->pair_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) putchar(' ');
                print_string_escaped(v->keys[i]);
                printf(": ");
                json_print(v->values[i], indent + 1);
                if (i < v->pair_count - 1) putchar(',');
                putchar('\n');
            }
            for (int s = 0; s < indent * 2; s++) putchar(' ');
            printf("}");
            break;
    }
}

static char *read_file(const char *path, long *out_size) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(size + 1);
    if (!buf) {
        fprintf(stderr, "Out of memory\n");
        exit(1);
    }
    size_t rd = fread(buf, 1, size, f);
    buf[rd] = '\0';
    fclose(f);
    *out_size = (long)rd;
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    long size_a, size_b;
    char *buf_a = read_file(path_a, &size_a);
    char *buf_b = read_file(path_b, &size_b);

    int pos_a = 0, pos_b = 0;
    json_value *a = json_parse(buf_a, &pos_a);
    json_value *b = json_parse(buf_b, &pos_b);

    free(buf_a);
    free(buf_b);

    json_value *merged = deep_merge(a, b);

    sort_object(merged);

    json_print(merged, 0);
    putchar('\n');

    json_free(a);
    json_free(b);
    json_free(merged);

    return 0;
}
